/*
 * Snippet to be included in rv_trace.h
 *
 * The declarations below correspond to the trace events generated by
 * DEFINE_EVENT when CONFIG_RV_MON_PAGEFAULT is enabled.
 */

#[cfg(CONFIG_RV_MON_PAGEFAULT)]
extern "C" {
    pub fn event_pagefault(
        task: *mut task_struct,
        states: *mut ::std::os::raw::c_char,
        atoms: *mut ::std::os::raw::c_char,
        next: *mut ::std::os::raw::c_char,
    );

    pub fn error_pagefault(task: *mut task_struct);
}

/* `task_struct` is supplied by the kernel dependency. */

